/**
 * The loan-word list (loans.tsv, generated by tools/build-data/build_loans.py):
 * English words used in Odia (CMUdict sounds, attested in IndicCorp) and
 * Persian / Arabic / Hindi / Turkish / Portuguese words from Praharaj, keyed
 * by English meaning. Found automatically; shown as such.
 */
import { canonical } from '../../../core/src/normalize.js';

export type LoanLanguage = 'en' | 'fa' | 'ar' | 'hi' | 'tr' | 'pt';

export interface Loan {
  english: string;
  odia: string;
  language: LoanLanguage;
  count: number;
}

export const LANGUAGE_LABEL: Readonly<Record<LoanLanguage, string>> = {
  en: 'English loan word',
  fa: 'From Persian',
  ar: 'From Arabic',
  hi: 'From Hindi',
  tr: 'From Turkish',
  pt: 'From Portuguese',
};

export interface LoanIndex {
  /** By lower-case English word or meaning, most common Odia word first. */
  byEnglish: Map<string, Loan[]>;
  /** By canonical Odia word. */
  byOdia: Map<string, Loan[]>;
  size: number;
}

export function parseLoans(tsv: string): LoanIndex {
  const byEnglish = new Map<string, Loan[]>();
  const byOdia = new Map<string, Loan[]>();
  let size = 0;
  for (const line of tsv.split('\n')) {
    if (!line || line.startsWith('#')) continue;
    const [english, odia, language, , count] = line.split('\t');
    if (!english || !odia || !language || !(language in LANGUAGE_LABEL)) continue;
    const loan: Loan = { english, odia: canonical(odia), language: language as LoanLanguage, count: Number(count) || 0 };
    for (const [map, key] of [[byEnglish, english], [byOdia, loan.odia]] as const) {
      const list = map.get(key) ?? [];
      list.push(loan);
      map.set(key, list);
    }
    size++;
  }
  for (const list of byEnglish.values()) list.sort((a, b) => b.count - a.count);
  return { byEnglish, byOdia, size };
}
